from __future__ import annotations

import asyncio
import logging
import pathlib
import time
from contextlib import asynccontextmanager
from typing import AsyncIterator

import attr
from taf.config.testline.testline import TestLine  # type: ignore[import-untyped]
from taf.gnb.oam.coam.cu import cu as taf_admin_cu  # type: ignore[import-untyped]
from urllib3.exceptions import MaxRetryError  # type: ignore[import-untyped]

from taf.ul.ue.sim.env_setup.devices.device import Device
from taf.ul.ue.sim.env_setup.utils.exceptions import ActivateException, UploadException, ValidateException
from taf.ul.ue.sim.env_setup.utils.scfc_utils import copy_scfc_to_output_dir
from taf.ul.ue.sim.env_setup.utils.tools import is_path_the_same


@attr.s(cmp=False, hash=True)
class VCU(Device):
    idx = attr.ib(type=int)
    configuration = attr.ib(type=TestLine, hash=False)
    bts_id = attr.ib(type=str)
    remote_host = attr.ib(type=str)
    output_directory_path = attr.ib(type=pathlib.Path)
    config_type = attr.ib(type=str)
    _user_flags = attr.ib(type=dict, hash=False)
    name = attr.ib(default="vcu", type=str, init=False)
    suite_config_dir = attr.ib(default="", type=str, init=False)
    scfc_name = attr.ib(default=None, type=pathlib.Path, init=False)
    _port = attr.ib(default="443", type=str, init=False)
    _user = attr.ib(default="Nemuadmin", type=str, init=False)
    _password = attr.ib(default="Nokia@123", type=str, init=False)
    _cu_version = attr.ib(default=None, type=str, init=False)

    def __attrs_post_init__(self):
        self._port = self.configuration.oam_http_connection_details.port
        self._user = self.configuration.oam_http_connection_details.username
        # self._password = self.configuration.oam_http_connection_details.password
        self.remote_host = self.remote_host or "localhost"
        self.logger.info(f"Created {self}")

    def _get_lmp_password(self) -> str:
        return "Nokia@123"

    async def configure(self) -> None:
        if self.scfc_name:
            await self._prepare_scfc()
            await self._perform_full_commissioning(self._user_flags.get("cloud_bts_recovery", True))
        else:
            self.logger.info("No SCFC provided. Configuration skipped.")

    async def _prepare_scfc(self):
        await self._copy_and_save_scfc()

    async def verify_all_is_up(self, timeout: float) -> None:
        alias = self._create_alias("verify_all_is_up")
        async with get_vcu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._cu_version, self.logger) as cu_admin:
            tasks = [
                self._verify_f1_links_available(cu_admin, alias, timeout),
                self._verify_cu_enabled(cu_admin, alias, timeout),
                self._verify_cu_onair(),
            ]
            await asyncio.gather(*tasks)

    async def _verify_f1_links_available(self, cu_admin: taf_admin_cu, alias: str, timeout: float) -> None:
        start_time = time.time()
        while (time.time() - start_time) < timeout:
            try:
                du_state = await asyncio.to_thread(cu_admin.get_du_state, connection=alias)
                f1_link_status = du_state["f1_link_status"]
                assert int(f1_link_status["unavailable"]) == 0 and int(
                    f1_link_status["available"] >= 1
                ), f"Not all F1 links available: {f1_link_status}"
                self.logger.info(f"All F1 links available: {f1_link_status}")
                break
            except AssertionError as err:
                self.logger.debug(err)
                await asyncio.sleep(5)
            except Exception as err:
                self.logger.debug(err, exc_info=True)

    async def _verify_cu_enabled(self, cu_admin: taf_admin_cu, alias: str, timeout: float) -> None:
        start_time = time.time()
        while (time.time() - start_time) < timeout:
            try:
                cu_state = await asyncio.to_thread(cu_admin.get_cu_state, connection=alias)
                assert (op_state := cu_state["operational_state"]) == "enabled", f"CU state is {op_state}, expected: 'enabled'"
                self.logger.info("CU operational state is 'enabled'")
                break
            except AssertionError as err:
                self.logger.debug(err)
                await asyncio.sleep(5)
            except Exception as err:
                self.logger.debug(err, exc_info=True)

    async def _verify_cu_onair(self) -> None:
        self.logger.debug("OnAir verification not implemented. No info available.")

    def _get_taf_pdu_config(self):
        raise NotImplementedError

    def _get_lmp_ip_for_ute(self) -> str:
        raise NotImplementedError

    def _get_lmp_ip_for_taf(self) -> str:
        return self.configuration.oam_http_connection_details.addr

    async def _perform_full_commissioning(self, recovery: bool):
        try:
            return await self.__perform_full_commissioning()
        except Exception as err:
            self.logger.debug(f"{type(err)}, {err = }")
            if not recovery:
                raise
            self.logger.debug(err)
            self.logger_recovery.info(err)
            await self._get_recovery_snapshot()
            await self._recovery_for_commissioning(str(err))
            return await self.__perform_full_commissioning()

    async def __perform_full_commissioning(self, timeout: float = 600):
        alias = self._create_alias("full_commissioning")
        async with get_vcu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._cu_version, self.logger) as cu_admin:
            plan_id = await self.upload(cu_admin, alias, timeout)
            await self.validate(cu_admin, alias, plan_id, timeout)
            await self.activate(cu_admin, alias, plan_id, timeout)

    async def _get_recovery_snapshot(self):
        if not self._user_flags.get("recovery_snapshot", False):
            self.logger.debug("Recovery snapshot disabled.")
            return
        alias = self._create_alias("recovery_snapshot")
        async with get_vcu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._cu_version, self.logger) as cu_admin:
            self.logger.debug("Trying to gather recovery snapshot")
            ret = await asyncio.to_thread(cu_admin.get_local_snapshot, self.output_directory_path.as_posix(), connection=alias)
            self.logger.debug(f"Recovery snapshot gathered to {self.output_directory_path} as {ret}")

    async def _recovery_for_commissioning(self, err_msg: str) -> None:
        alias = self._create_alias("recovery_for_commissioning")
        if "Insufficient Storage" in err_msg:
            await self._delete_all_plans(alias)
        await self._reset_via_admin(alias)

    async def _reset_via_admin(self, alias: str) -> None:
        async with get_vcu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._cu_version, self.logger) as vcu_admin:
            ret = await asyncio.to_thread(vcu_admin.reset_cu, connection=alias)
            self.logger.debug(f"{ret = }")

    async def upload(self, cu_admin: taf_admin_cu, alias: str, timeout: float) -> str:
        start_time = time.time()
        ret = await asyncio.to_thread(cu_admin.upload_plan_file, self.scfc_name, connection=alias)
        action_id = ret["action_id"]
        while (time.time() - start_time) < timeout:
            op_state = await asyncio.to_thread(cu_admin.get_operation_state_of_uploading_plan, action_id, connection=alias)
            self.logger.debug(f"UPLOAD: {op_state}")
            if (status := op_state["status"]) == "ongoing":
                pass
            elif status == "success":
                return ret["plan_id"]
            elif status == "failure":
                break
            else:
                self.logger.warning("Unexpected state.")
            await asyncio.sleep(1)
        raise UploadException(f"Failed to upload plan within timeout {timeout}s")

    async def validate(self, cu_admin: taf_admin_cu, alias: str, plan_id: str, timeout: float):
        start_time = time.time()
        ret = await asyncio.to_thread(cu_admin.plan_validation, plan_id, connection=alias)
        action_id = ret["action_id"]
        while (time.time() - start_time) < timeout:
            op_state = await asyncio.to_thread(cu_admin.get_operation_state_of_validating_plan, plan_id, action_id, connection=alias)
            self.logger.debug(f"VALIDATE: {op_state}")
            if (status := op_state["status"]) == "ongoing":
                pass
            elif status == "success":
                return
            elif status == "failure":
                break
            else:
                self.logger.warning("Unexpected state.")
            await asyncio.sleep(1)
        raise ValidateException(f"Validation failed after {time.time() - start_time}s. Timeout: {timeout}")

    async def activate(self, cu_admin: taf_admin_cu, alias: str, plan_id: str, timeout: float) -> None:
        start_time = time.time()
        ret = await asyncio.to_thread(cu_admin.plan_activation, plan_id, connection=alias)
        action_id = ret["id"]
        while (time.time() - start_time) < timeout:
            try:
                op_state = await asyncio.to_thread(cu_admin.get_operation_state_of_activating_plan, plan_id, action_id, connection=alias)
                self.logger.debug(f"ACTIVATE {op_state}")
                if (status := op_state["status"]) == "ongoing":
                    pass
                elif status == "success":
                    return
                elif status == "failure":
                    break
                else:
                    self.logger.warning("Unexpected state.")
                await asyncio.sleep(5)
            except MaxRetryError:
                await asyncio.sleep(3)
            except Exception as err:
                if "Service Unavailable" in str(err):
                    self.logger.debug("CU reset ongoing.")
                    await asyncio.sleep(30)
                else:
                    self.logger.debug(f"ACTIVATE ERR: {type(err)}, {err}")
                await asyncio.sleep(1)
        raise ActivateException(f"Activation failed after {time.time() - start_time}s. Timeout: {timeout}")

    async def _delete_all_plans(self, alias: str) -> None:
        async with get_vcu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._cu_version, self.logger) as cu_admin:
            await asyncio.gather(
                *[self.__delete_plan(cu_admin, plan, alias) for plan in await asyncio.to_thread(cu_admin.get_staged_plans_list, connection=alias)]
            )
            assert len(await asyncio.to_thread(cu_admin.get_staged_plans_list, connection=alias)) == 0

    async def __delete_plan(self, cu_admin: taf_admin_cu, plan: dict, alias: str) -> None:
        self.logger.debug(f"Removing plan: {plan}")
        await asyncio.to_thread(cu_admin.plan_delete, plan["plan_id"], connection=alias)
        self.logger.debug(f"Plan {plan} removed")

    async def _copy_and_save_scfc(self):
        new_scfc_path = self.output_directory_path.joinpath(self.scfc_name.name)
        if not is_path_the_same(self.scfc_name, new_scfc_path, self.logger):
            await asyncio.to_thread(copy_scfc_to_output_dir, self.scfc_name, self.output_directory_path)
        self.scfc_name = new_scfc_path


@asynccontextmanager
async def get_vcu_admin_connection(
    alias: str, host: str, port: str, user: str, password: str, version: str | None, logger: logging.Logger
) -> AsyncIterator[taf_admin_cu]:
    admin_cu = taf_admin_cu()
    try:
        logger.debug(f"SETUP START: vCU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
        if version is None:
            await asyncio.to_thread(admin_cu.connect_to, host, port, user, password, secure=True, alias=alias)
        else:
            await asyncio.to_thread(admin_cu.connect_to, host, port, user, password, cu_version=version, secure=True, alias=alias)
        logger.debug(f"SETUP DONE: vCU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
        yield admin_cu
    finally:
        logger.debug(f"TEARDOWN START: vCU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
        try:
            await asyncio.to_thread(admin_cu.disconnect, connection=alias)
        except Exception as err:
            logger.debug(err)
        logger.debug(f"TEARDOWN DONE: vCU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
